    langFixed: true,              // англ.: фиксированно 16 Listening + 18 Grammar + 16 Reading
    total: 130,                   // 50 + 30 + 30 + 20
    thresholdTotal: 75,           // задано пользователем
    timeMin: 210,                 // ~3.5 часа как на реальном КТ (условно)
